import { roles } from '../lib/palettes.js';
import { buildPaletteCheckReport, checkVisionModes } from '../lib/palette-checks.js';
const checkEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const checkIndex=index=>String(index+1).padStart(2,'0');
function renderColorChecks(palette,theme,role,settings){
 const colors=palette.themes[theme][role],report=buildPaletteCheckReport(palette,theme,role,settings),background=report.background,active=report.modes[settings.vision];
 const options=(items,value)=>items.map(([id,label])=>`<option value="${id}" ${String(value)===String(id)?'selected':''}>${label}</option>`).join('');
 const pairName=pair=>`${checkIndex(pair.a)} ↔ ${checkIndex(pair.b)}`;
 const pairRows=pairs=>pairs.map(pair=>`<tr><td title="${checkEscape(colors[pair.a].name+' ↔ '+colors[pair.b].name)}"><i style="background:${active.samples[pair.a].hex}"></i>${pairName(pair)}<i style="background:${active.samples[pair.b].hex}"></i></td><td>${pair.delta.toFixed(2)}</td><td class="${pair.delta<settings.deltaThreshold?'check-caution':'check-ok'}">${pair.delta<settings.deltaThreshold?'低于参考值':'≥参考值'}</td></tr>`).join('');
 const pairTable=pairs=>`<table class="check-table"><thead><tr><th>颜色对</th><th>ΔE</th><th>提示</th></tr></thead><tbody>${pairRows(pairs)}</tbody></table>`;
 return `<section class="panel-section color-check-panel"><div class="section-heading"><span class="section-label">色值检验</span><span class="check-context">${theme==='light'?'浅色':'深色'} · ${colors.length} 色</span></div><p class="check-note">${checkEscape(palette.name)} · ${roles[role]}<br>按当前色板计算，不改变预览中的颜色。</p><div class="check-controls"><label>检验对象<select data-check-field="role" aria-label="检验颜色角色">${options(Object.entries(roles),role)}</select></label><label>图形背景<select data-check-field="background" aria-label="检验背景">${options([['card','卡片背景'],['page','页面背景'],['custom','自定义背景']],settings.background)}</select></label>${settings.background==='custom'?`<label>背景色<input type="color" data-check-field="customBackground" aria-label="检验背景色" value="${settings.customBackground}"></label>`:''}<label>图形不透明度<span><input type="number" min="1" max="100" step="1" data-check-field="opacity" aria-label="图形不透明度" value="${Math.round(settings.opacity*100)}"> %</span></label></div></section>
 <section class="panel-section color-check-panel"><h3>1 · OKLCH / OKLab</h3><p class="check-note">L 明度、C 彩度、h 色相；用于描述颜色位置。</p><div class="check-result check-ok">${report.validCount}/${colors.length} OKLCH 数值有效</div><div class="check-ranges"><span>L 范围<strong>${report.lightnessRange.map(v=>v.toFixed(1)+'%').join(' – ')}</strong></span><span>C 范围<strong>${report.chromaRange.map(v=>v.toFixed(3)).join(' – ')}</strong></span></div><details class="check-details"><summary>查看每个颜色的 L / C / h</summary><table class="check-table"><thead><tr><th>色号</th><th>L%</th><th>C</th><th>h°</th></tr></thead><tbody>${report.entries.map(entry=>`<tr><td title="${checkEscape(entry.name)}"><i style="background:${entry.hex}"></i>${checkIndex(entry.index)}</td><td>${(entry.value.l*100).toFixed(1)}</td><td>${entry.value.c.toFixed(3)}</td><td>${entry.value.h===null?'—':entry.value.h.toFixed(1)}</td></tr>`).join('')}</tbody></table></details><p class="check-note">此项仅判断 OKLCH 数值有效性；L 相近表示感知明度相近，不等于对背景的对比度相同。</p></section>
 <section class="panel-section color-check-panel"><h3>2 · ΔE 色差</h3><p class="check-note">ΔE = OKLab 欧氏距离 × 100。数值越小，两色越接近。</p><div class="check-controls"><label>参考阈值<input type="number" min="0" max="100" step="1" data-check-field="deltaThreshold" aria-label="ΔE 参考阈值" value="${settings.deltaThreshold}"></label><label>色差视觉<select data-check-field="vision" aria-label="色差视觉模拟">${options(Object.entries(checkVisionModes),settings.vision)}</select></label></div><div class="check-sim-swatches" aria-label="${checkVisionModes[settings.vision]}模拟色板">${active.samples.map((sample,index)=>`<span title="${checkEscape(colors[index].name)}"><i style="background:${sample.hex}"></i><small>${checkIndex(index)}</small></span>`).join('')}</div><table class="check-table check-vision-summary"><thead><tr><th>视觉</th><th>最近色对</th><th>最小 ΔE</th></tr></thead><tbody>${Object.entries(report.modes).map(([vision,data])=>`<tr><td>${checkVisionModes[vision].replace('色觉缺陷','色缺陷')}</td><td>${data.nearest?pairName(data.nearest):'—'}</td><td class="${data.nearest&&data.nearest.delta<settings.deltaThreshold?'check-caution':''}">${data.nearest?data.nearest.delta.toFixed(2):'—'}</td></tr>`).join('')}</tbody></table>${active.nearest?`<div class="check-result ${active.closeCount?'check-caution':'check-ok'}">${active.closeCount}/${active.pairs.length} 对低于参考阈值 ${settings.deltaThreshold}</div>${pairTable(active.pairs.slice(0,8))}${active.pairs.length>8?`<details class="check-details"><summary>查看其余 ${active.pairs.length-8} 对</summary>${pairTable(active.pairs.slice(8))}</details>`:''}`:'<p class="check-note">不足两色，无色差比较。</p>'}<p class="check-note">阈值为可调整的筛查参考，不是统一合格线。色觉缺陷采用 Machado 重度模拟，蓝色缺陷为近似。</p></section>
 <section class="panel-section color-check-panel"><h3>3 · 对比度</h3><p class="check-note">WCAG 相对亮度比：(较亮 + 0.05) / (较暗 + 0.05)。</p><div class="check-controls"><label>参考要求<select data-check-field="contrastTarget" aria-label="对比度参考要求">${options([[3,'图形 3:1'],[4.5,'普通文字 4.5:1'],[7,'增强文字 7:1']],settings.contrastTarget)}</select></label></div><div class="check-background"><i style="background:${background}"></i>背景 ${background} · 不透明度 ${Math.round(settings.opacity*100)}%</div><div class="check-result ${report.contrastPass===colors.length?'check-ok':'check-caution'}">${report.contrastPass}/${colors.length} 色达到 ${settings.contrastTarget}:1</div><table class="check-table"><thead><tr><th>颜色</th><th>对比度</th><th>提示</th></tr></thead><tbody>${report.entries.map(entry=>`<tr><td title="${checkEscape(entry.name+' '+entry.hex)}"><i style="background:${entry.hex}"></i>${checkIndex(entry.index)}</td><td>${entry.contrast.toFixed(2)}:1</td><td class="${entry.contrast>=settings.contrastTarget?'check-ok':'check-caution'}">${entry.contrast>=settings.contrastTarget?'达到参考值':'低于参考值'}</td></tr>`).join('')}</tbody></table><p class="check-note">色差和对比度使用叠加背景后的显示色。此处按纯色和统一透明度估算；渐变、细线及相邻扇区仍需结合实际图形检查，不代表整张图已满足 WCAG。</p><div class="check-sources"><a href="https://www.w3.org/TR/css-color-4/#ok-lab" target="_blank" rel="noopener noreferrer">OKLab / OKLCH</a><a href="https://www.w3.org/WAI/WCAG22/Understanding/non-text-contrast" target="_blank" rel="noopener noreferrer">WCAG 图形对比度</a><a href="https://doi.org/10.1109/TVCG.2009.113" target="_blank" rel="noopener noreferrer">模拟模型</a></div></section>`;
}
export {renderColorChecks};

export function renderColorCheckBadges(entry,report){
 const {settings}=report,nearest=entry.nearest;
 const other=nearest?report.entries[nearest.a===entry.index?nearest.b:nearest.a]:null;
 const deltaTitle=nearest?`${checkVisionModes[settings.vision]}：最近颜色 ${checkIndex(other.index)} ${other.name}，ΔE ${nearest.delta.toFixed(2)}；要求 ≥ ${settings.deltaThreshold}`:'不足两色，无色差比较';
 const badge=(metric,label,pass,title)=>`<span data-check-metric="${metric}" data-passed="${pass===null?'na':pass}" class="color-check-badge ${pass===null?'check-neutral':pass?'check-ok':'check-caution'}" title="${checkEscape(title)}" aria-label="${label}：${pass===null?'无比较对象':pass?metric==='oklch'?'数值有效':'达到参考要求':'未达到参考要求'}">${label} ${pass===null?'—':pass?'✓':'✕'}</span>`;
 return badge('oklch','OKLCH',entry.oklchPass,'判断 L、C、h 数值是否有效；不设统一配色优劣阈值')+badge('delta','ΔE',entry.deltaPass,deltaTitle)+badge('contrast','对比度',entry.contrastPass,`与背景 ${report.background} 的对比度 ${entry.contrast.toFixed(2)}:1；要求 ≥ ${settings.contrastTarget}:1；不透明度 ${Math.round(settings.opacity*100)}%`);
}
